export function apportion(total,weights){const sum=weights.reduce((a,b)=>a+b,0);if(!sum)return weights.map(()=>0);const exact=weights.map(w=>total*w/sum),result=exact.map(Math.floor);let left=total-result.reduce((a,b)=>a+b,0);const order=exact.map((n,i)=>({i,r:n-result[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let k=0;k<left;k++)result[order[k%order.length].i]++;return result}
export function calculate(people,items,tax,service,discount){const subtotal=items.reduce((s,i)=>s+i.price,0),net=subtotal+tax+service-discount;const weights=people.map(()=>0);let unassigned=0;for(const item of items){const owners=people.map((p,i)=>item.owners.includes(p.id)?i:-1).filter(i=>i>=0);if(!owners.length)unassigned++;else for(const i of owners)weights[i]+=item.price/owners.length}const valid=items.length>0&&people.length>0&&subtotal>0&&net>=0&&!unassigned&&items.every(i=>i.name.trim()&&Number.isSafeInteger(i.price)&&i.price>=0);return {subtotal,net,unassigned,valid,weights,shares:valid?apportion(net,weights):people.map(()=>0)}}
export function moneyValue(raw){let s=String(raw).replace(/[^\d.,]/g,'');if(/[,\.]\d{2}$/.test(s)){s=s.slice(0,-3).replace(/[.,]/g,'')}else s=s.replace(/[.,]/g,'');return Number(s)||0}
export function parseReceipt(text){const out={items:[],tax:0,service:0,discount:0,total:null};for(const raw of text.split(/\n/)){const line=raw.trim();if(!line)continue;const m=line.match(/(?:Rp\.?\s*)?(\d[\d.,]*)\s*$/i);if(!m)continue;const amount=moneyValue(m[1]);const before=line.slice(0,m.index).trim();if(!before||amount>1000000000)continue;if(/subtotal|sub\s+total/i.test(before))continue;if(/grand\s*total|total\s*(bayar|tagihan|akhir)?\s*[:=]?$/i.test(before)){out.total=amount;continue}if(/tax|pajak|ppn|pb1/i.test(before)){out.tax+=amount;continue}if(/service|servis|svc|pelayanan/i.test(before)){out.service+=amount;continue}if(/discount|diskon|disc\b|potongan/i.test(before)){out.discount+=amount;continue}if(/cash|tunai|change|kembali|debit|credit|card|qris|payment|paid|pembayaran|bayar|telp|phone|npwp|tanggal|date|time|table|meja|order|receipt|invoice|kasir|cashier|no\s*[.:#]|jumlah item|total item/i.test(before))continue;let name=before.replace(/^\d+\s*[xX]\s*/,'').replace(/^\d+\s+(?=[A-Za-z])/,'').replace(/\s+\d[\d.,]*\s*$/,'').trim();if(name.length<2||!/[a-zA-Z]/.test(name)||/[/:]/.test(name))continue;out.items.push({name,price:amount,owners:[]})}return out}
